"""Install the generated workspace's npm dependencies before each TDD run."""

from pathlib import Path
import subprocess
from threading import Thread

from infrastructure.utils.processes import npm_command, start_process, stop_process


def install_dependencies(output_dir: Path) -> None:
    """Run npm install in the generated workspace, stream its output, and fail on timeout or nonzero exit."""
    if not (output_dir / "package.json").is_file():
        raise ValueError("Run 00_project_initialization.py before installing project dependencies")
    command = npm_command()
    print(f"Installing dependencies in {output_dir}: npm install --include=dev --no-audit --no-fund", flush=True)
    with start_process(
        [*command, "install", "--include=dev", "--no-audit", "--no-fund"],
        cwd=output_dir, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
        text=True, encoding="utf-8", errors="replace", bufsize=1,
    ) as process:
        # Forward child output through Python so the console log also receives it.
        def forward_output():
            """Forward npm output through Python so both the terminal and compiler.log receive it."""
            for line in process.stdout:
                print(line, end="", flush=True)

        reader = Thread(target=forward_output, daemon=True)
        reader.start()
        try:
            process.wait(timeout=600)
        except subprocess.TimeoutExpired as error:
            stop_process(process)
            raise RuntimeError("npm install timed out after 600 seconds") from error
        except BaseException:
            stop_process(process)
            raise
        finally:
            reader.join()
        if process.returncode:
            raise RuntimeError(f"npm install failed with exit code {process.returncode}; see the npm output above")
"""Cross-platform process startup, UTF-8 output, npm resolution, and owned-tree cleanup."""

import os
from pathlib import Path
import shutil
import signal
import subprocess

WINDOWS = os.name == "nt"


def child_environment(overrides=None) -> dict:
    """Keep inherited settings while making Python child output consistently UTF-8."""
    return {**os.environ, **(overrides or {}), "PYTHONUTF8": "1", "PYTHONIOENCODING": "utf-8"}


def process_options() -> dict:
    """Create an owned process group using the host platform's supported API."""
    if WINDOWS:
        return {"creationflags": getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0x00000200)}
    return {"start_new_session": True}


def start_process(command, *, cwd, env=None, **options):
    """Launch an argument list without shell interpolation, preserving spaces and Unicode paths."""
    return subprocess.Popen([str(part) for part in command], cwd=cwd,
        env=child_environment(env), **process_options(), **options)


def stop_process(process) -> None:
    """Stop only the owned process tree on interruption/timeout, including browser/server children."""
    if WINDOWS:
        # Killing node.exe alone leaves its Playwright/Vite descendants running.
        subprocess.run([shutil.which("taskkill") or "taskkill", "/PID", str(process.pid), "/T", "/F"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=10, check=False)
    else:
        try:
            os.killpg(process.pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        try:
            process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            pass
        # The parent can exit before a descendant; clean the remaining group too.
        try:
            os.killpg(process.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
    if process.poll() is None:
        process.kill()
    process.wait(timeout=5)


def capture_process(command, *, cwd, timeout, env=None) -> dict:
    """Capture UTF-8 output and clean the whole process tree before re-raising timeout or Ctrl+C."""
    process = start_process(command, cwd=cwd, env=env, stdout=subprocess.PIPE,
        stderr=subprocess.PIPE, text=True, encoding="utf-8", errors="replace")
    try:
        stdout, stderr = process.communicate(timeout=timeout)
    except BaseException:
        stop_process(process)
        process.communicate(timeout=5)
        raise
    return {"returncode": process.returncode, "stdout": stdout,
        "output": (stdout + stderr)[-24000:]}


def npm_command() -> list[str]:
    """Resolve npm through its JavaScript CLI, avoiding Windows .cmd shell quoting."""
    node, npm = shutil.which("node"), shutil.which("npm")
    if not node or not npm:
        raise ValueError("Node.js and npm are required; install them and add their executables to PATH")
    node = str(Path(node).resolve())
    launcher = Path(npm).resolve()
    if launcher.suffix.lower() in {".js", ".mjs"}:
        return [node, str(launcher)]
    for directory in (launcher.parent, Path(node).resolve().parent):
        script = directory / "node_modules/npm/bin/npm-cli.js"
        if script.is_file():
            return [node, str(script)]
    if launcher.suffix.lower() in {".cmd", ".bat", ".ps1"}:
        raise ValueError("Cannot locate npm-cli.js beside the npm/Node launcher; use a complete Node.js installation")
    # Unix installations may expose an executable script rather than a JS symlink.
    return [str(launcher)]
"""Index requirement containment while retaining each scenario's step context."""

import json


# --- Extension point: requirement representation and traversal ----------------
# Extend normalization or reference handling here. Stable IDs, explicit step
# ownership, and correct postorder are shared contracts of steps 02 through 04.
class RequirementTree:
    """Normalized requirement and scenario indexes with explicit step ownership and traversal order."""
    def __init__(self, root: dict) -> None:
        """Index requirements and scenario steps while validating IDs and ownership.

        Build children, own_steps, leaf order, and child-before-parent postorder
        once so later stages share the same containment semantics."""
        self.requirements = {}
        self.steps = {}
        self.children = {}
        self.own_steps = {}
        self.postorder = []

        def identifier(node, kind):
            """Read a requirement, scenario or step ID from the JSON document."""
            if not isinstance(node, dict) or not isinstance(node.get("id"), str) or not node["id"].strip():
                raise ValueError(f"Each {kind} must have a nonempty string id")
            return node["id"]

        def items(node, key):
            """Read an optional list field and reject malformed child, scenario, step, or reference collections."""
            value = node.get(key, [])
            if not isinstance(value, list):
                raise ValueError(f"{key} must be a list: {node['id']}")
            return value

        def visit(node):
            """Index one requirement and its own steps, recurse into children, then append its postorder ID."""
            rid = identifier(node, "requirement")
            description = node.get("description", "")
            if isinstance(description, dict):
                description = description.get("text", "")
            if not isinstance(description, str) or not isinstance(node.get("name", ""), str):
                raise ValueError(f"Invalid name or description: {rid}")
            self.requirements[rid] = {"id": rid, "name": node.get("name", ""), "description": description}
            self.own_steps[rid] = []
            for scenario in items(node, "scenarios"):
                sid = identifier(scenario, "scenario")
                for step in items(scenario, "steps"):
                    step_id = identifier(step, "step")
                    record = {"id": step_id, "scenario": {"id": sid, "name": scenario.get("name", "")}}
                    for key in ("Given", "When", "Then"):
                        record[key] = step.get(key, step.get(key.lower(), ""))
                        if not isinstance(record[key], str):
                            raise ValueError(f"{key} must be text: {step_id}")
                    record["references"] = items(step, "references")
                    self.steps[step_id] = record
                    self.own_steps[rid].append(step_id)
            self.children[rid] = [visit(child) for child in items(node, "children")]
            self.postorder.append(rid)
            return rid

        visit(root)
        # Only leaves own model-driven business analysis; parents aggregate results.
        self.leaves = [rid for rid in self.requirements if not self.children[rid]]

    def concatenated_steps(self, requirement_id: str) -> str:
        """Render only this requirement's own steps, preserving scenario labels, Given/When/Then, and references."""
        lines = []
        previous_scenario = None
        for step_id in self.own_steps[requirement_id]:
            step = self.steps[step_id]
            scenario = step["scenario"]
            if scenario["id"] != previous_scenario:
                lines.append(f"Scenario {scenario['id']}: {scenario['name']}")
                previous_scenario = scenario["id"]
            lines.append(f"Step {step_id}")
            lines.extend(f"{key}: {step[key]}" for key in ("Given", "When", "Then"))
            if step["references"]:
                lines.append("References: " + json.dumps(step["references"], ensure_ascii=False))
        return "\n".join(lines)
"""Small JSON-generating text model client."""

import json
import os
from pathlib import Path

from dotenv import load_dotenv
from openai import OpenAI, OpenAIError
from infrastructure.utils.presentation.model_io import http_client, invoke


class TextModel:
    """Transport for structured stage proposals and file-edit responses."""
    def __init__(self) -> None:
        """Read compiler/.env and configure the text model client; reject missing credentials or model name."""
        load_dotenv(Path(__file__).resolve().parents[3] / ".env", encoding="utf-8-sig")
        self.name = os.getenv("MODEL")
        api_key = os.getenv("OPENAI_API_KEY")
        if not self.name or not api_key:
            raise ValueError("Set MODEL and OPENAI_API_KEY in compiler/.env")
        try:
            self.max_output_tokens = int(os.getenv("MAX_OUTPUT_TOKENS", "32768"))
        except ValueError as error:
            raise ValueError("MAX_OUTPUT_TOKENS must be a positive integer") from error
        if self.max_output_tokens < 1:
            raise ValueError("MAX_OUTPUT_TOKENS must be a positive integer")
        self._token_parameter = "max_completion_tokens"
        self.client = OpenAI(
            api_key=api_key,
            base_url=os.getenv("OPENAI_BASE_URL") or "https://api.openai.com/v1",
            timeout=120, max_retries=2,
            http_client=http_client(),
        )

    def _request(self, **arguments):
        """Apply one output budget to JSON calls, with legacy endpoint compatibility."""
        try:
            response = invoke(self.client, {**arguments, self._token_parameter: self.max_output_tokens})
        except OpenAIError as error:
            # Some compatible endpoints only support the older max_tokens name.
            # Retry only an explicit parameter rejection, not arbitrary failures.
            message = str(error).lower()
            unsupported = any(word in message for word in ("unsupported", "unknown", "unrecognized", "not supported", "not allowed", "unexpected"))
            if self._token_parameter != "max_completion_tokens" or getattr(error, "status_code", None) not in {400, 422} or "max_completion_tokens" not in message or not unsupported:
                raise
            self._token_parameter = "max_tokens"
            response = invoke(self.client, {**arguments, "max_tokens": self.max_output_tokens})
        # Detect transport truncation before attempting to parse partial JSON.
        if response.choices and response.choices[0].finish_reason == "length":
            raise ValueError(
                f"Model output was truncated (finish_reason=length; MAX_OUTPUT_TOKENS={self.max_output_tokens}). "
                "Increase MAX_OUTPUT_TOKENS if the model supports a larger budget, or implement smaller files."
            )
        return response

    def generate_json(self, instructions: str, payload: dict) -> dict:
        """Request one ordinary JSON object; stage code owns examples and structural/semantic validation."""
        try:
            response = self._request(
                model=self.name,
                messages=[
                    {"role": "system", "content": instructions.rstrip() + "\nReturn exactly one JSON object without Markdown."},
                    {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
                ],
                response_format={"type": "json_object"},
            )
        except OpenAIError as error:
            raise RuntimeError(f"Text model request failed: {error}") from error
        if response.choices and getattr(response.choices[0].message, "refusal", None):
            raise ValueError(f"Text model refused the request: {response.choices[0].message.refusal}")
        if not response.choices or not response.choices[0].message.content:
            raise ValueError("Text model returned empty content")
        content = response.choices[0].message.content.strip()
        try:
            result = json.loads(content)
        except json.JSONDecodeError as error:
            # Some compatible endpoints append a second JSON object or a short
            # explanation after an otherwise complete object. Decode the first
            # object only; the stage's schema/semantic gate still decides whether
            # that object is acceptable.
            try:
                candidate, end = json.JSONDecoder().raw_decode(content)
            except json.JSONDecodeError:
                raise error
            if not isinstance(candidate, dict) or not content[end:].strip():
                raise error
            result = candidate
        if not isinstance(result, dict):
            raise ValueError("Text model must return a JSON object")
        return result
"""Full SDK and HTTP model I/O audit, with concise progress on the terminal."""

from datetime import datetime, timezone
import json
from time import monotonic
from uuid import uuid4
from contextvars import ContextVar

import httpx

from infrastructure.utils.presentation.console import current_activity, preview, show_panel, WaitingStatus
from infrastructure.utils.presentation.logging import session_info


_call = ContextVar("compiler_model_call", default=None)


def _record(event: str, **data) -> None:
    """Append untruncated values; never record authentication headers."""
    call = _call.get()
    session = session_info()
    if not session:
        return
    record = {"timestamp": datetime.now(timezone.utc).isoformat(),
        "stage": session["stage"], "call_id": call["id"] if call else None,
        "activity": call["activity"] if call else current_activity(), "event": event, **data}
    with session["lock"]:
        with (session["output"] / "model_calls.jsonl").open("a", encoding="utf-8", newline="\n") as log:
            log.write(json.dumps(record, ensure_ascii=False) + "\n")


def _http_request(request: httpx.Request) -> None:
    """Capture the actual serialized body on every HTTP attempt, including retries."""
    _record("http_request", method=request.method, url=str(request.url.copy_with(query=None)),
        body=request.content.decode("utf-8"))


def _http_response(response: httpx.Response) -> None:
    """Read and retain the complete non-streaming response before SDK parsing."""
    response.read()
    _record("http_response", status_code=response.status_code,
        request_id=response.headers.get("x-request-id"), body=response.text)


def http_client() -> httpx.Client:
    """Install hooks beneath SDK retries, preserving the SDK's transport limits."""
    from openai import DefaultHttpxClient
    return DefaultHttpxClient(event_hooks={"request": [_http_request], "response": [_http_response]})


def _input_summary(arguments: dict) -> str:
    messages = arguments.get("messages", [])
    lines = [f"Model: {arguments.get('model')} | Messages: {len(messages)}"]
    for message in messages:
        content = message.get("content", "")
        if isinstance(content, str):
            line = f"{message['role']}: {len(content):,} characters"
            if message["role"] == "user":
                try:
                    payload = json.loads(content)
                except ValueError:
                    payload = None
                if isinstance(payload, dict):
                    line += " | sections: " + ", ".join(payload)
                    files = payload.get("files")
                    if isinstance(files, dict):
                        writable = sum(bool(item.get("writable")) for item in files.values() if isinstance(item, dict))
                        line += f" | files: {len(files)} ({writable} writable)"
            lines.append(line)
        else:
            lines.append(f"{message['role']}: text and image parts ({len(content)})")
    return "\n".join(lines)


def _output_preview(content: str) -> str:
    """Show readable JSON or source excerpts, including the affected file paths."""
    try:
        value = json.loads(content)
    except ValueError:
        return preview(content)
    if isinstance(value, dict) and isinstance(value.get("edits"), list):
        edits = value["edits"]
        lines = [f"File edits: {len(edits)}"]
        for edit in edits[:8]:
            if isinstance(edit, dict):
                source = edit.get("content", "")
                lines.append(f"{edit.get('path', '(unknown path)')} ({len(str(source)):,} characters)")
        if len(edits) > 8:
            lines.append(f"... {len(edits) - 8} more file edits")
        for edit in edits[:3]:
            if isinstance(edit, dict) and isinstance(edit.get("content"), str):
                lines.extend([f"\n--- {edit.get('path')} ---", preview(edit["content"], max_lines=12, max_chars=1400)])
        return "\n".join(lines)
    return preview(json.dumps(value, ensure_ascii=False, indent=2), max_lines=40, max_chars=6000)


def invoke(client, arguments: dict):
    """Audit one SDK call and show a static waiting message until it returns."""
    call_id = uuid4().hex
    activity = current_activity()
    session = session_info()
    label = f"{session['stage']} | {activity}" if session else activity
    token = _call.set({"id": call_id, "activity": activity})
    started = monotonic()
    show_panel(f"[MODEL INPUT] {label} | call {call_id[:8]}", _input_summary(arguments), tone="input", max_lines=12, max_chars=1600)
    waiting = WaitingStatus()

    try:
        _record("request", arguments=arguments)
        response = client.chat.completions.create(**arguments)
        # Preserve the SDK envelope and untouched message content before any JSON repair.
        raw = response.model_dump(mode="json")
        _record("response", elapsed_seconds=monotonic() - started, response=raw)
        waiting.close()
        content = "\n".join(choice.message.content or "" for choice in response.choices)
        show_panel(f"[MODEL OUTPUT] {label} | {monotonic() - started:.1f}s",
            _output_preview(content or json.dumps(raw, ensure_ascii=False)), tone="output", max_lines=60, max_chars=8500)
        return response
    except BaseException as error:
        waiting.close()
        _record("error", elapsed_seconds=monotonic() - started,
            error_type=type(error).__name__, message=str(error))
        show_panel(f"[MODEL FAILED] {label}", f"{type(error).__name__}: {error}", tone="error", max_lines=12, max_chars=1800)
        raise
    finally:
        waiting.close()
        _call.reset(token)

